insert into public.editorial_content_items (id,kind,payload,sort_order,created_at,updated_at,author_email) values
('marketing-monitoring-master-stakeholder-call', 'research_resource', '{"editorialSurface": "page", "pagePath": "/programs/marketing", "sectionId": "marketing-monitoring-master", "entryType": "section", "title": "Шановні стейкхолдери!", "summary": "Опитування щодо удосконалення ОПП", "body": "<!-- APSVT_RICH_TEXT_V1 -->\n{\"type\":\"doc\",\"content\":[{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Кафедра маркетингу Академії праці, соціальних відносин і туризму запрошує роботодавців, представників професійної та академічної спільноти, здобувачів вищої освіти, випускників та інших заінтересованих осіб долучитися до обговорення та удосконалення освітньо-професійної програми «Маркетинг» другого (магістерського) рівня вищої освіти за спеціальністю D5 «Маркетинг».\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Для кафедри важливо враховувати думку стейкхолдерів щодо актуальності змісту освітньої програми, її відповідності сучасним тенденціям розвитку маркетингової науки і практики, потребам ринку праці, цифровим трансформаціям та вимогам до професійних компетентностей сучасного фахівця з маркетингу.\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Просимо Вас долучитися до опитування: \"},{\"type\":\"text\",\"text\":\"завантажити й заповнити анкету\",\"marks\":[{\"type\":\"link\",\"attrs\":{\"href\":\"/documents/marketing/surveys/master-stakeholders-2026.docx\"}}]},{\"type\":\"text\",\"text\":\" та надіслати її на електронну адресу кафедри: \"},{\"type\":\"text\",\"text\":\"academi.marketing2023@gmail.com\",\"marks\":[{\"type\":\"link\",\"attrs\":{\"href\":\"mailto:academi.marketing2023@gmail.com\"}}]},{\"type\":\"text\",\"text\":\". Ваші оцінки, зауваження та пропозиції будуть розглянуті проєктною (робочою) групою ОПП «Маркетинг» та використані під час моніторингу, перегляду й подальшого удосконалення освітньої програми.\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Особливо цінними для нас є Ваші пропозиції щодо актуальних професійних компетентностей, змісту освітніх компонентів, практичної підготовки здобувачів, використання сучасних цифрових технологій та інструментів, а також перспективних напрямів розвитку маркетингу.\"}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Щиро дякуємо за співпрацю та внесок у підвищення якості підготовки майбутніх фахівців з маркетингу!\"}]},{\"type\":\"blockquote\",\"content\":[{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"Надія Писаренко\",\"marks\":[{\"type\":\"bold\"}]}]},{\"type\":\"paragraph\",\"content\":[{\"type\":\"text\",\"text\":\"завідувач кафедри маркетингу · +380 99 961 05 97 · \"},{\"type\":\"text\",\"text\":\"nadezda_pisarenko@ukr.net\",\"marks\":[{\"type\":\"link\",\"attrs\":{\"href\":\"mailto:nadezda_pisarenko@ukr.net\"}}]}]}]}]}", "fileUrl": "", "fileName": "", "status": "published"}'::jsonb, 10, '2026-11-04T00:00:00.000Z', '2026-11-04T00:00:00.000Z', 'editorial@apsvt.local'),
